From 14a0db9580fe86e1e832bdad264208ee4be971c4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:18:22 +0100
Subject: [PATCH] ksplash: show a user-chosen background image on the splash
 screen

Using the default splash screen with another background meant installing
a whole new theme. ksplashqml now reads a Background image from the
ksplashrc file or --background, and the Breeze splash screen shows it.

BUG: 355250
---
 ksplash/ksplashqml/splashapp.cpp                      | 8 +++++++-
 ksplash/ksplashqml/splashapp.h                        | 1 +
 ksplash/ksplashqml/splashwindow.cpp                   | 6 +++++-
 ksplash/ksplashqml/splashwindow.h                     | 3 ++-
 lookandfeel/org.kde.breeze/contents/splash/Splash.qml | 9 +++++++++
 5 files changed, 24 insertions(+), 3 deletions(-)

diff --git a/ksplash/ksplashqml/splashapp.cpp b/ksplash/ksplashqml/splashapp.cpp
index ba011d183f..66257b4f25 100644
--- a/ksplash/ksplashqml/splashapp.cpp
+++ b/ksplash/ksplashqml/splashapp.cpp
@@ -51,6 +51,7 @@ SplashApp::SplashApp(int &argc, char **argv)
     parser.addOption(QCommandLineOption(QStringLiteral("window"), QStringLiteral("Run in windowed mode")));
     parser.addOption(QCommandLineOption(QStringLiteral("nofork"), QStringLiteral("Don't fork")));
     parser.addOption(QCommandLineOption(QStringLiteral("pid"), QStringLiteral("Print the pid of the child process")));
+    parser.addOption(QCommandLineOption(QStringLiteral("background"), QStringLiteral("Background image to show"), QStringLiteral("file")));
     parser.addPositionalArgument(QStringLiteral("theme"), QStringLiteral("Path to the theme to test"));
     parser.addHelpOption();

@@ -64,6 +65,11 @@ SplashApp::SplashApp(int &argc, char **argv)
             m_theme = ksplashCfg.readEntry("Theme", QStringLiteral("Breeze"));
         }
     }
+    if (parser.isSet(QStringLiteral("background"))) {
+        m_background = parser.value(QStringLiteral("background"));
+    } else {
+        m_background = KSharedConfig::openConfig()->group(QStringLiteral("KSplash")).readEntry("Background", QString());
+    }

     if (!m_testing) {
         QDBusServiceWatcher* watcher = new QDBusServiceWatcher(QStringLiteral("org.kde.PlasmaLoading"), QDBusConnection::sessionBus(), QDBusServiceWatcher::WatchForUnregistration, this);
@@ -116,7 +122,7 @@ void SplashApp::adoptScreen(QScreen *screen)
     if (screen->geometry().isNull()) {
         return;
     }
-    auto *w = new SplashWindow(m_engine.get(), m_testing, m_window, m_theme, screen);
+    auto *w = new SplashWindow(m_engine.get(), m_testing, m_window, m_theme, m_background, screen);
     w->setGeometry(screen->geometry());
     w->setStage(m_stage);
     w->setVisible(true);
diff --git a/ksplash/ksplashqml/splashapp.h b/ksplash/ksplashqml/splashapp.h
index a2236b4bf5..37601b1136 100644
--- a/ksplash/ksplashqml/splashapp.h
+++ b/ksplash/ksplashqml/splashapp.h
@@ -32,6 +32,7 @@ private:
     bool m_window;
     QBasicTimer m_timer;
     QString m_theme;
+    QString m_background;
     std::shared_ptr<QQmlEngine> m_engine;

 private Q_SLOTS:
diff --git a/ksplash/ksplashqml/splashwindow.cpp b/ksplash/ksplashqml/splashwindow.cpp
index 2553be09a8..f4609c9426 100644
--- a/ksplash/ksplashqml/splashwindow.cpp
+++ b/ksplash/ksplashqml/splashwindow.cpp
@@ -25,12 +25,13 @@

 using namespace Qt::StringLiterals;

-SplashWindow::SplashWindow(QQmlEngine *engine, bool testing, bool window, const QString &theme, QScreen *screen)
+SplashWindow::SplashWindow(QQmlEngine *engine, bool testing, bool window, const QString &theme, const QString &background, QScreen *screen)
     : QQuickView(engine, nullptr)
     , m_stage(0)
     , m_testing(testing)
     , m_window(window)
     , m_theme(theme)
+    , m_background(background)
 {
     if (auto layerShellWindow = LayerShellQt::Window::get(this)) {
         layerShellWindow->setScope(QStringLiteral("ksplashqml"));
@@ -130,5 +131,8 @@ void SplashWindow::setGeometry(const QRect &rect)
                 exit(1);
             }
         };
+        if (rootObject() && !m_background.isEmpty()) {
+            rootObject()->setProperty("backgroundImage", QUrl::fromUserInput(m_background, QString(), QUrl::AssumeLocalFile));
+        }
     }
 }
diff --git a/ksplash/ksplashqml/splashwindow.h b/ksplash/ksplashqml/splashwindow.h
index 1d1edf14b3..feb8597912 100644
--- a/ksplash/ksplashqml/splashwindow.h
+++ b/ksplash/ksplashqml/splashwindow.h
@@ -15,7 +15,7 @@ class QKeyEvent;
 class SplashWindow : public QQuickView
 {
 public:
-    SplashWindow(QQmlEngine *engine, bool testing, bool window, const QString &theme, QScreen *screen);
+    SplashWindow(QQmlEngine *engine, bool testing, bool window, const QString &theme, const QString &background, QScreen *screen);

     void setStage(int stage);
     virtual void setGeometry(const QRect &rect);
@@ -29,4 +29,5 @@ private:
     const bool m_testing;
     const bool m_window;
     const QString m_theme;
+    const QString m_background;
 };
diff --git a/lookandfeel/org.kde.breeze/contents/splash/Splash.qml b/lookandfeel/org.kde.breeze/contents/splash/Splash.qml
index 71aab92bec..d194d7d58e 100644
--- a/lookandfeel/org.kde.breeze/contents/splash/Splash.qml
+++ b/lookandfeel/org.kde.breeze/contents/splash/Splash.qml
@@ -12,6 +12,7 @@ Rectangle {
     color: "black"

     property int stage
+    property url backgroundImage

     onStageChanged: {
         if (stage == 2) {
@@ -29,6 +30,14 @@ Rectangle {
         anchors.fill: parent
         opacity: 0

+        Image {
+            anchors.fill: parent
+            asynchronous: true
+            source: root.backgroundImage
+            fillMode: Image.PreserveAspectCrop
+            sourceSize: Qt.size(width * Screen.devicePixelRatio, height * Screen.devicePixelRatio)
+        }
+
         Image {
             id: logo
             //match SDDM/lockscreen avatar positioning
-- 
